const HELP = ownFacts({ id: 'crew-1|camera||3|2026-11-15T12:00:00.000Z', level: 3, system: 'Help key', indicator: null });
const MOOD = ownFacts({ id: 'crew-1|mood||2|now', level: 2, system: 'Mind', indicator: 'mood' });
